def solve(expr):
    def apply_op(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def evaluate(expression):
        stack = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = 0
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                stack.append(num)
                i -= 1
            elif expression[i] in '+-*/':
                while stack and stack[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = stack.pop()
                    stack.append(apply_op(op, a, b))
                stack.append(expression[i])
            elif expression[i] == '(':
                stack.append(expression[i])
            elif expression[i] == ')':
                while stack[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = stack.pop()
                    stack.append(apply_op(op, a, b))
                stack.pop()  # Remove '(' from stack
            i += 1

        while stack and len(stack) > 1:
            b = stack.pop()
            a = stack.pop()
            op = stack.pop()
            stack.append(apply_op(op, a, b))

        return stack[0]

    return evaluate(expr)

# Example usage:
print(solve("3 + 5 * (2 - 3)"))  # Output: -4
